package com.oms.service;import com.oms.config.Db;import com.oms.dao.*;import com.oms.model.User;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;
public class ReconciliationService{public record PageData(FinanceOverviewDao.LedgerData ledger,List<ReconciliationDao.Document> documents,Long portalCustomerId){}private final ReconciliationDao dao=new ReconciliationDao();private final FinanceOverviewDao finance=new FinanceOverviewDao();private final AuditLogDao audit=new AuditLogDao();public PageData page(User viewer,boolean portal)throws SQLException{try(Connection c=Db.getConnection()){Long customer=portal?dao.portalCustomer(c,viewer.getId()):null;if(portal&&customer==null)throw new ForbiddenException("Tài khoản chưa gắn với đại lý.");var ledger=finance.ledger(c);if(portal)ledger=new FinanceOverviewDao.LedgerData(ledger.customers().stream().filter(x->x.id()==customer).toList(),ledger.entries().stream().filter(x->x.customerId()==customer).toList());return new PageData(ledger,dao.list(c,customer),customer);}}public long generate(long customer,LocalDate start,LocalDate end,User actor)throws SQLException{if(customer<=0||start==null||end==null||start.isAfter(end))throw new ServiceException("Kỳ đối chiếu không hợp lệ.");return Db.inTransaction(c->{var ledger=finance.ledger(c);if(ledger.customers().stream().noneMatch(x->x.id()==customer))throw new ServiceException("Đại lý không tồn tại.");BigDecimal opening=ledger.entries().stream().filter(x->x.customerId()==customer&&x.date().isBefore(start)).map(x->x.increase().subtract(x.decrease())).reduce(BigDecimal.ZERO,BigDecimal::add),increase=ledger.entries().stream().filter(x->x.customerId()==customer&&!x.date().isBefore(start)&&!x.date().isAfter(end)).map(FinanceOverviewDao.LedgerEntry::increase).reduce(BigDecimal.ZERO,BigDecimal::add),decrease=ledger.entries().stream().filter(x->x.customerId()==customer&&!x.date().isBefore(start)&&!x.date().isAfter(end)).map(FinanceOverviewDao.LedgerEntry::decrease).reduce(BigDecimal.ZERO,BigDecimal::add);String code=String.format("DCN%06d",dao.next(c));long id;try{id=dao.insert(c,code,customer,start,end,opening,increase,decrease,actor.getId());}catch(SQLException e){throw new ServiceException("Kỳ này đã có biên bản đối chiếu.");}audit.log(c,actor.getId(),"RECONCILIATION_CREATE","RECONCILIATION",id,code);return id;});}public void respond(long id,String status,String reason,User actor)throws SQLException{if(!Set.of("ACCEPTED","DISPUTED").contains(status))throw new ServiceException("Phản hồi không hợp lệ.");String clean=reason==null?"":reason.strip();if("DISPUTED".equals(status)&&clean.length()<10)throw new ServiceException("Nêu chênh lệch ít nhất 10 ký tự.");Db.inTransaction(c->{Long customer=dao.portalCustomer(c,actor.getId());if(customer==null)throw new ForbiddenException("Tài khoản chưa gắn đại lý.");dao.respond(c,id,customer,status,clean);audit.log(c,actor.getId(),"RECONCILIATION_"+status,"RECONCILIATION",id,clean);return null;});}}
